package com.digitalbase.ticketing.model;import jakarta.persistence.*;import lombok.*;import java.time.LocalDateTime;@Entity@Table(name = "otps")@Data@Builder@NoArgsConstructor@AllArgsConstructorpublic class Otp {    @Id    @GeneratedValue(strategy = GenerationType.IDENTITY)    private Long id;    @Column(nullable = false)    private String email;    @Column(name = "otp_code", nullable = false)    private String otpCode;    @Column(name = "reset_token", unique = true)    private String resetToken;    @Column(name = "expiry_date", nullable = false)    private LocalDateTime expiryDate;}